2	// Hand-authored helpers shared by the novel commands (ground, items recent,
3	// cite, collections tree, cache status/reindex). Kept out of generated files
4	// so regen-merge preserves them.
5	
6	package cli
7	
8	import (
9		"context"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"strings"
14	
15		"zotero-research-library-pp-cli/internal/client"
16		"zotero-research-library-pp-cli/internal/store"
17	)
18	
19	// apiErrStatus extracts the HTTP status from a client error, or 0.
20	func apiErrStatus(err error) int {
21		var apiErr *client.APIError
22		if errors.As(err, &apiErr) {
23			return apiErr.StatusCode
24		}
25		return 0
26	}
27	
28	// zoteroItemData is the subset of a Zotero item's nested `data` object the
29	// novel commands read. The API envelope is {key, version, data:{...}}.
30	type zoteroItemData struct {
31		Key              string          `json:"key"`
32		ItemType         string          `json:"itemType"`
33		Title            string          `json:"title"`
34		AbstractNote     string          `json:"abstractNote"`
35		Date             string          `json:"date"`
36		DateAdded        string          `json:"dateAdded"`
37		DOI              string          `json:"DOI"`
38		PublicationTitle string          `json:"publicationTitle"`
39		Extra            string          `json:"extra"`
40		ParentItem       string          `json:"parentItem"`
41		Collections      []string        `json:"collections"`
42		Creators         []zoteroCreator `json:"creators"`
43	}
44	
45	type zoteroCreator struct {
46		CreatorType string `json:"creatorType"`
47		FirstName   string `json:"firstName"`
48		LastName    string `json:"lastName"`
49		Name        string `json:"name"`
50	}
51	
52	// decodeItemData unwraps the nested `data` object from a stored item envelope.
53	func decodeItemData(raw []byte) (zoteroItemData, error) {
54		var envelope struct {
55			Key  string         `json:"key"`
56			Data zoteroItemData `json:"data"`
57		}
58		if err := json.Unmarshal(raw, &envelope); err != nil {
59			return zoteroItemData{}, err
60		}
61		d := envelope.Data
62		if d.Key == "" {
63			d.Key = envelope.Key
64		}
65		return d, nil
66	}
67	
68	// creatorSummary renders "Last, Last & Last" (capped at three surnames) for
69	// human and JSON output. Institutional creators use their single Name field.
70	func creatorSummary(creators []zoteroCreator) string {
71		var names []string
72		for _, c := range creators {
73			switch {
74			case c.LastName != "":
75				names = append(names, c.LastName)
76			case c.Name != "":
77				names = append(names, c.Name)
78			}
79		}
80		if len(names) == 0 {
81			return ""
82		}
83		if len(names) > 3 {
84			return strings.Join(names[:3], ", ") + " et al."
85		}
86		if len(names) > 1 {
87			return strings.Join(names[:len(names)-1], ", ") + " & " + names[len(names)-1]
88		}
89		return names[0]
90	}
91	
92	// ftsQuote wraps every user-supplied term as a quoted FTS5 string so
93	// punctuation (hyphens, apostrophes, colons) can't be parsed as FTS syntax.
94	func ftsQuote(query string) string {
95		terms := strings.Fields(query)
96		quoted := make([]string, 0, len(terms))
97		for _, t := range terms {
98			quoted = append(quoted, `"`+strings.ReplaceAll(t, `"`, `""`)+`"`)
99		}
100		return strings.Join(quoted, " ")
101	}
102	
103	// resolveCollectionKey resolves a user-supplied collection reference — exact
104	// key first, then case-insensitive name match — against the local cache.
105	func resolveCollectionKey(ctx context.Context, db *store.Store, ref string) (string, error) {
106		// Dedicated columns are empty on this envelope-nested API — the id
107		// column holds the collection key and the name lives in the JSON.
108		row := db.DB().QueryRowContext(ctx,
109			`SELECT "id" FROM "collections" WHERE "id" = ?`, ref)
110		var key string
111		if err := row.Scan(&key); err == nil {
112			return key, nil
113		}
114		rows, err := db.DB().QueryContext(ctx,
115			`SELECT "id", COALESCE(json_extract("data", '$.data.name'), '')
116			 FROM "collections"
117			 WHERE LOWER(json_extract("data", '$.data.name')) LIKE LOWER(?)
118			 ORDER BY 2 LIMIT 5`,
119			"%"+ref+"%")
120		if err != nil {
121			return "", err
122		}
123		defer rows.Close()
124		var matches [][2]string
125		for rows.Next() {
126			var k, n string
127			if err := rows.Scan(&k, &n); err != nil {
128				return "", err
129			}
130			matches = append(matches, [2]string{k, n})
131		}
132		if err := rows.Err(); err != nil {
133			return "", err
134		}
135		switch len(matches) {
136		case 0:
137			return "", fmt.Errorf("no collection matches %q (run 'collections tree' to browse)", ref)
138		case 1:
139			return matches[0][0], nil
140		default:
141			var names []string
142			for _, m := range matches {
143				names = append(names, fmt.Sprintf("%s (%s)", m[1], m[0]))
144			}
145			return "", fmt.Errorf("collection %q is ambiguous: %s", ref, strings.Join(names, ", "))
146		}
147	}
148	
149	// requireLocalCache opens the store read-only and converts the two empty
150	// states (no DB file, open error) into actionable messages.
151	func requireLocalCache(ctx context.Context, cliName string) (*store.Store, error) {
152		db, err := openStoreForRead(ctx, cliName)
153		if err != nil {
154			return nil, fmt.Errorf("opening local cache: %w", err)
155		}
156		if db == nil {
157			return nil, fmt.Errorf("local cache is empty — run '%s sync --full' first", cliName)
158		}
159		return db, nil
160	}
