1	// Copyright 2026 Eric Rash and contributors. Licensed under Apache-2.0. See LICENSE.
2	// Hand-authored novel command: offline research-grounding search.
3	// pp:data-source local
4	
5	package cli
6	
7	import (
8		"context"
9		"fmt"
10		"sort"
11		"strconv"
12		"strings"
13	
14		"github.com/spf13/cobra"
15		"zotero-research-library-pp-cli/internal/store"
16	)
17	
18	func init() {
19		registerNovelCommand(func(root *cobra.Command, flags *rootFlags) {
20			addNovelCommandIfAbsent(root, newNovelGroundCmd(flags))
21		})
22	}
23	
24	type groundHit struct {
25		Key         string  `json:"key"`
26		Title       string  `json:"title"`
27		Creators    string  `json:"creators,omitempty"`
28		Date        string  `json:"date,omitempty"`
29		Publication string  `json:"publication,omitempty"`
30		DOI         string  `json:"doi,omitempty"`
31		ItemType    string  `json:"item_type,omitempty"`
32		Snippet     string  `json:"snippet,omitempty"`
33		MatchedIn   string  `json:"matched_in"`
34		ParentKey   string  `json:"parent_key,omitempty"`
35		ParentTitle string  `json:"parent_title,omitempty"`
36		rank        float64 `json:"-"`
37	}
38	
39	func newNovelGroundCmd(flags *rootFlags) *cobra.Command {
40		var flagLimit int
41		var flagFulltext bool
42		var flagCollection string
43		var flagLive bool
44	
45		cmd := &cobra.Command{
46			Use:   "ground <query>...",
47			Short: "Ranked full-text search over your synced library — offline, with snippets and citation-ready metadata",
48			Long: `Answers "what does my library say about X?" from the local cache: ranked
49	FTS5 search over titles, abstracts, creators, and tags, with snippets and
50	citation-ready metadata. No network, no rate limit.
51	
52	--fulltext matches indexed attachment text (populate it once with
53	'cache index-fulltext') and resolves each hit to its parent paper. --live
54	bypasses the cache and runs the query server-side via qmode=everything.`,
55			Example: `  zotero-research-library-pp-cli ground "hamstring injury prevention" --limit 10 --agent
56	  zotero-research-library-pp-cli ground "nordic hamstring" --fulltext --agent
57	  zotero-research-library-pp-cli ground "acl injury" --collection HAMSTRING --limit 5`,
58			Args:        cobra.MinimumNArgs(1),
59			Annotations: map[string]string{"mcp:read-only": "true", "pp:happy-args": "<query>=hamstring"},
60			RunE: func(cmd *cobra.Command, args []string) error {
61				if dryRunOK(flags) {
62					return nil
63				}
64				query := strings.TrimSpace(strings.Join(args, " "))
65				if query == "" {
66					return fmt.Errorf("query must not be empty")
67				}
68				if flagLimit <= 0 {
69					flagLimit = 10
70				}
71	
72				if flagLive {
73					return groundLive(cmd, flags, query, flagLimit)
74				}
75	
76				ctx := cmd.Context()
77				db, err := requireLocalCache(ctx, "zotero-research-library-pp-cli")
78				if err != nil {
79					return err
80				}
81				defer db.Close()
82	
83				collectionKey := ""
84				if flagCollection != "" {
85					collectionKey, err = resolveCollectionKey(ctx, db, flagCollection)
86					if err != nil {
87						return err
88					}
89				}
90	
91				hits, err := groundSearch(ctx, db, query, flagLimit, flagFulltext, collectionKey)
92				if err != nil {
93					return err
94				}
95	
96				if flags.asJSON {
97					return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
98						"query":   query,
99						"source":  "local",
100						"count":   len(hits),
101						"results": hits,
102					}, flags)
103				}
104				out := cmd.OutOrStdout()
105				if len(hits) == 0 {
106					fmt.Fprintf(out, "No matches for %q in the local cache.\n", query)
107					if flagFulltext {
108						fmt.Fprintln(out, "Attachment text must be indexed first: run 'cache index-fulltext'.")
109					} else {
110						fmt.Fprintln(out, "If the cache may be stale, run 'sync' — or retry with --live for a server-side search.")
111					}
112					return nil
113				}
114				for i, h := range hits {
115					fmt.Fprintf(out, "%2d. %s", i+1, h.Title)
116					if h.Creators != "" {
117						fmt.Fprintf(out, " — %s", h.Creators)
118					}
119					if h.Date != "" {
120						fmt.Fprintf(out, " (%s)", h.Date)
121					}
122					fmt.Fprintf(out, "\n    key=%s", h.Key)
123					if h.DOI != "" {
124						fmt.Fprintf(out, "  doi=%s", h.DOI)
125					}
126					if h.Publication != "" {
127						fmt.Fprintf(out, "  %s", h.Publication)
128					}
129					fmt.Fprintln(out)
130					if h.Snippet != "" {
131						fmt.Fprintf(out, "    %s\n", h.Snippet)
132					}
133				}
134				return nil
135			},
136		}
137		cmd.Flags().IntVar(&flagLimit, "limit", 10, "Maximum results to return")
138		cmd.Flags().BoolVar(&flagFulltext, "fulltext", false, "Match indexed attachment full text (see 'cache index-fulltext'); resolve hits to parent papers")
139		cmd.Flags().StringVar(&flagCollection, "collection", "", "Restrict to a collection (key or name)")
140		cmd.Flags().BoolVar(&flagLive, "live", false, "Run the query server-side (qmode=everything) instead of the local cache")
141		return cmd
142	}
143	
144	// groundSearch runs the ranked local search. The primary source is
145	// resources_fts, whose content column holds every searchable leaf value of
146	// the item JSON (title, abstract, creators, tags). A second pass over
147	// items_fts covers attachment full text populated by 'cache index-fulltext';
148	// in --fulltext mode that pass is the only source.
149	func groundSearch(ctx context.Context, db *store.Store, query string, limit int, fulltextOnly bool, collectionKey string) ([]groundHit, error) {
150		match := ftsQuote(query)
151	
152		collectionFilter := ""
153		var collectionArgs []any
154		if collectionKey != "" {
155			collectionFilter = ` AND EXISTS (SELECT 1 FROM json_each(json_extract(i."data", '$.data.collections')) je WHERE je.value = ?)`
156			collectionArgs = append(collectionArgs, collectionKey)
157		}
158	
159		seen := map[string]bool{}
160		var hits []groundHit
161	
162		if !fulltextOnly {
163			// resources_fts carries id/resource_type as stored columns with
164			// hashed rowids — join on the id column, never on rowid.
165			primarySQL := `SELECT i."data", snippet("resources_fts", 2, '[', ']', ' … ', 12), bm25("resources_fts")
166				FROM "resources_fts"
167				JOIN "items" i ON i."id" = "resources_fts".id
168				WHERE "resources_fts".resource_type = 'items' AND "resources_fts" MATCH ?` + collectionFilter + `
169				ORDER BY bm25("resources_fts") LIMIT ?`
170			args := append([]any{"content: (" + match + ")"}, collectionArgs...)
171			args = append(args, limit*2)
172			rows, err := db.DB().QueryContext(ctx, primarySQL, args...)
173			if err != nil {
174				return nil, fmt.Errorf("local search: %w", err)
175			}
176			defer rows.Close()
177			for rows.Next() {
178				var raw []byte
179				var snip string
180				var rank float64
181				if err := rows.Scan(&raw, &snip, &rank); err != nil {
182					return nil, err
183				}
184				h, ok := buildGroundHit(ctx, db, raw, snip, rank, "metadata", false)
185				if !ok || seen[h.Key] {
186					continue
187				}
188				seen[h.Key] = true
189				hits = append(hits, h)
190			}
191			if err := rows.Err(); err != nil {
192				return nil, err
193			}
194		}
195	
196		// Attachment full text lives in the items.content column (populated by
197		// 'cache index-fulltext') and is indexed by items_fts.
198		fulltextSQL := `SELECT i."data", snippet("items_fts", 1, '[', ']', ' … ', 12), bm25("items_fts")
199			FROM "items_fts" JOIN "items" i ON i.rowid = "items_fts".rowid
200			WHERE "items_fts" MATCH ?` + collectionFilter + `
201			ORDER BY bm25("items_fts") LIMIT ?`
202		fArgs := append([]any{"content: (" + match + ")"}, collectionArgs...)
203		fArgs = append(fArgs, limit*2)
204		frows, err := db.DB().QueryContext(ctx, fulltextSQL, fArgs...)
205		if err == nil {
206			defer frows.Close()
207			for frows.Next() {
208				var raw []byte
209				var snip string
210				var rank float64
211				if err := frows.Scan(&raw, &snip, &rank); err != nil {
212					break
213				}
214				// Full-text matches rank slightly behind exact metadata matches
215				// unless --fulltext asked for them specifically.
216				adj := rank
217				if !fulltextOnly {
218					adj += 0.5
219				}
220				h, ok := buildGroundHit(ctx, db, raw, snip, adj, "attachment fulltext", true)
221				if !ok || seen[h.Key] {
222					continue
223				}
224				seen[h.Key] = true
225				hits = append(hits, h)
226			}
227		}
228	
229		sort.SliceStable(hits, func(a, b int) bool { return hits[a].rank < hits[b].rank })
230		if len(hits) > limit {
231			hits = hits[:limit]
232		}
233		return hits, nil
234	}
235	
236	// buildGroundHit decodes a stored item row into a result. Attachment and note
237	// rows resolve to their parent paper when one exists, keeping the attachment's
238	// snippet while citation metadata comes from the parent.
239	func buildGroundHit(ctx context.Context, db *store.Store, raw []byte, snippet string, rank float64, matchedIn string, resolveParent bool) (groundHit, bool) {
240		d, err := decodeItemData(raw)
241		if err != nil || d.Key == "" {
242			return groundHit{}, false
243		}
244		h := groundHit{
245			Key:         d.Key,
246			Title:       d.Title,
247			Creators:    creatorSummary(d.Creators),
248			Date:        d.Date,
249			Publication: d.PublicationTitle,
250			DOI:         d.DOI,
251			ItemType:    d.ItemType,
252			Snippet:     strings.TrimSpace(snippet),
253			MatchedIn:   matchedIn,
254			rank:        rank,
255		}
256		if (d.ItemType == "attachment" || d.ItemType == "note") && d.ParentItem != "" {
257			var parentRaw []byte
258			row := db.DB().QueryRowContext(ctx, `SELECT "data" FROM "items" WHERE "id" = ?`, d.ParentItem)
259			if err := row.Scan(&parentRaw); err == nil {
260				if p, perr := decodeItemData(parentRaw); perr == nil && p.Key != "" {
261					h.ParentKey = d.Key
262					h.ParentTitle = d.Title
263					h.Key = p.Key
264					h.Title = p.Title
265					h.Creators = creatorSummary(p.Creators)
266					h.Date = p.Date
267					h.Publication = p.PublicationTitle
268					h.DOI = p.DOI
269					h.ItemType = p.ItemType
270				}
271			} else if resolveParent {
272				h.MatchedIn = matchedIn + " (parent not in cache)"
273			}
274		}
275		// Attachments matched only on filename noise aren't research results.
276		if h.Title == "" {
277			return groundHit{}, false
278		}
279		return h, true
280	}
281	
282	// groundLive runs the query server-side via the generated items endpoint's
283	// full search grammar (qmode=everything covers server-side full text).
284	func groundLive(cmd *cobra.Command, flags *rootFlags, query string, limit int) error {
285		c, err := flags.newClient()
286		if err != nil {
287			return err
288		}
289		params := map[string]string{
290			"q":     query,
291			"qmode": "everything",
292			"limit": strconv.Itoa(limit),
293		}
294		data, err := c.Get(cmd.Context(), "/items", params)
295		if err != nil {
296			return classifyAPIError(err, flags)
297		}
298		if flags.asJSON {
299			return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
300				"query":   query,
301				"source":  "live",
302				"results": data,
303			}, flags)
304		}
