2	// Hand-authored novel command: Better BibTeX citekey bridge.
3	// pp:data-source local
4	
5	package cli
6	
7	import (
8		"bytes"
9		"context"
10		"encoding/json"
11		"fmt"
12		"net/http"
13		"strings"
14		"time"
15	
16		"github.com/spf13/cobra"
17	)
18	
19	// bbtEndpoint is Better BibTeX's local JSON-RPC endpoint, served by the
20	// Zotero desktop app when the BBT plugin is installed.
21	const bbtEndpoint = "http://127.0.0.1:23119/better-bibtex/json-rpc"
22	
23	func newNovelCiteCmd(flags *rootFlags) *cobra.Command {
24		var flagFormat string
25	
26		cmd := &cobra.Command{
27			Use:   "cite <citekey>",
28			Short: "Resolve a Better BibTeX citekey to its item and export citekey-faithful BibTeX",
29			Long: `Bridges Better BibTeX citekeys (the identifiers manuscripts actually use)
30	to library items. BibTeX export goes through the desktop app's Better BibTeX
31	JSON-RPC endpoint so the exported entry keeps the exact citekey; when the
32	desktop is closed, the command falls back to the local cache's extra-field
33	citekeys and reports what it could and couldn't do.`,
34			Example: `  zotero-research-library-pp-cli cite smithHamstring2024 --format bibtex
35	  zotero-research-library-pp-cli cite smithHamstring2024 --format json --agent`,
36			Args: cobra.ExactArgs(1),
37			// pp:interactive — the happy path depends on the Zotero desktop app
38			// (Better BibTeX JSON-RPC) being open, which the dogfood harness
39			// cannot guarantee.
40			Annotations: map[string]string{"mcp:read-only": "true", "pp:interactive": "true"},
41			RunE: func(cmd *cobra.Command, args []string) error {
42				if dryRunOK(flags) {
43					return nil
44				}
45				citekey := strings.TrimSpace(args[0])
46				if citekey == "" {
47					return fmt.Errorf("citekey must not be empty")
48				}
49				switch flagFormat {
50				case "", "bibtex", "json":
51				default:
52					return fmt.Errorf("unsupported --format %q (use bibtex or json)", flagFormat)
53				}
54				ctx := cmd.Context()
55	
56				if flagFormat == "" || flagFormat == "bibtex" {
57					bib, err := bbtExport(ctx, citekey)
58					if err == nil {
59						if flags.asJSON {
60							return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
61								"citekey": citekey,
62								"format":  "bibtex",
63								"source":  "better-bibtex-rpc",
64								"bibtex":  bib,
65							}, flags)
66						}
67						fmt.Fprintln(cmd.OutOrStdout(), bib)
68						return nil
69					}
70					// Desktop closed or BBT absent: fall through to the cache.
71					fmt.Fprintf(cmd.ErrOrStderr(), "note: Better BibTeX JSON-RPC unavailable (%v); falling back to the local cache\n", err)
72				}
73	
74				db, err := requireLocalCache(ctx, "zotero-research-library-pp-cli")
75				if err != nil {
76					return err
77				}
78				defer db.Close()
79	
80				// BBT pins citekeys in the item's extra field as
81				// "Citation Key: <key>" when so configured.
82				rows, err := db.DB().QueryContext(ctx,
83					`SELECT "data" FROM "items" WHERE "data" LIKE ? LIMIT 5`,
84					"%Citation Key: "+citekey+"%")
85				if err != nil {
86					return fmt.Errorf("searching cache for citekey: %w", err)
87				}
88				defer rows.Close()
89				for rows.Next() {
90					var raw []byte
91					if err := rows.Scan(&raw); err != nil {
92						return err
93					}
94					d, derr := decodeItemData(raw)
95					if derr != nil || !hasCitationKey(d.Extra, citekey) {
