15	func newNovelCacheStatusCmd(flags *rootFlags) *cobra.Command {
16	
17		cmd := &cobra.Command{
18			Use:         "status",
19			Short:       "Sync cursors, row and FTS counts, and last-sync age from the local cache",
20			Long:        "Reports cache health without touching the network: per-resource sync cursors and ages, row counts, how many items carry indexed full text, FTS index size, and the database file itself. Use before trusting offline 'ground' results.",
21			Example:     "  zotero-research-library-pp-cli cache status --agent",
22			Annotations: map[string]string{"mcp:read-only": "true"},
23			RunE: func(cmd *cobra.Command, args []string) error {
24				if dryRunOK(flags) {
25					return nil
26				}
27				ctx := cmd.Context()
28				dbPath := defaultDBPath("zotero-research-library-pp-cli")
29				db, err := requireLocalCache(ctx, "zotero-research-library-pp-cli")
30				if err != nil {
31					return err
32				}
33				defer db.Close()
34	
35				type resourceState struct {
36					Resource   string `json:"resource"`
37					Rows       int    `json:"rows"`
38					LastSynced string `json:"last_synced,omitempty"`
39					AgeHours   *int   `json:"age_hours,omitempty"`
40					Cursor     string `json:"cursor,omitempty"`
41				}
42				var states []resourceState
43				srows, err := db.DB().QueryContext(ctx,
44					`SELECT resource_type, COALESCE(last_cursor, ''), COALESCE(last_synced_at, ''), total_count
45					 FROM sync_state ORDER BY resource_type`)
46				if err != nil {
47					return fmt.Errorf("reading sync state: %w", err)
48				}
49				defer srows.Close()
50				for srows.Next() {
51					var rs resourceState
52					var syncedAt string
53					if err := srows.Scan(&rs.Resource, &rs.Cursor, &syncedAt, &rs.Rows); err != nil {
54						return err
55					}
56					// Zero-value or pre-epoch timestamps mean "never completed" —
57					// rendering them as an age would show hundreds of years.
58					if t, terr := time.Parse(time.RFC3339, syncedAt); terr == nil && t.Year() > 1971 {
59						rs.LastSynced = syncedAt
60						age := int(time.Since(t).Hours())
61						rs.AgeHours = &age
62					}
63					states = append(states, rs)
64				}
65				if err := srows.Err(); err != nil {
66					return err
67				}
68	
